last=None
for s in episode['shots']:
 scene=int(s['id'][1:3])
 if scene!=last:
  f+=['\n'+headings[scene]+'\n'];last=scene
 f += [f'[[{s["id"]} | {tc(s["start_frame"])}–{tc(s["end_frame"])} | {s["frames"]} frames | SOURCE SHOT]]\n',field(s,'Action')+'\n']
 qs=re.findall('“([^”]+)”',s['script'])
 if s['id'] in speakers:
  assert len(qs)==len(speakers[s['id']]),s['id']
  for sp,q in zip(speakers[s['id']],qs):f += ['\n@'+sp+'\n'+q+'\n']
 f+=['\n!SOUND: '+field(s,'Sound')+'\n','[[CAMERA / DRAWING: '+s['script'].splitlines()[0].split(' · ',1)[-1]+'; FX: '+field(s,'FX').replace('`','')+']]\n']
 if field(s,'Note'):f+=['[[SOURCE NOTE: '+field(s,'Note')+']]\n']
ed=source.split('### ED · End card and ending (1:30, not in shots.json)')[1].split('\n---')[0].strip()
f+=['\n.ENDING — SEPARATELY PLANNED\n\n'+ed+'\n\n[[ED is not part of the 27,120-frame body. episode.json declares 2,160 ED frames; whether the final ten-second black is included remains unresolved.]]\n']
save('SCRIPT.fountain','\n'.join(f))
